        "id": "luma-brandkit-character-library",
        "source_lang": "en",
        "eyebrow": "AI NEWS",
        "tool": "Movies",
        "source": "Luma AI",
        "url": "https://lumalabs.ai/news/brand-kit-character-library",
        "accent": "#0070f3",
